(function(global){
  function escPdf(value){return String(value==null?"":value).replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)").replace(/\r?\n/g," ")}
  function JsPDF(){this._pages=[[]];this._fontSize=10;this.internal={getNumberOfPages:()=>this._pages.length};this.lastAutoTable={finalY:40}}
  JsPDF.prototype.setFontSize=function(size){this._fontSize=Number(size)||10;return this};
  JsPDF.prototype._page=function(){return this._pages[this._pages.length-1]};
  JsPDF.prototype.addPage=function(){this._pages.push([]);return this};
  JsPDF.prototype.text=function(text,x,y){this._page().push({text:String(text==null?"":text),x:Number(x)||20,y:Number(y)||20,size:this._fontSize});return this};
  JsPDF.prototype.line=function(x1,y1,x2,y2){this._page().push({line:[Number(x1)||0,Number(y1)||0,Number(x2)||0,Number(y2)||0]});return this};
  JsPDF.prototype.save=function(filename){
    var objects=[];var pages=[];var fontId=0;
    function addObject(body){objects.push(body);return objects.length}
    fontId=addObject("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
    this._pages.forEach(function(items){
      var content="";items.forEach(function(item){
        if(item.line){content+=item.line[0].toFixed(2)+" "+(595-item.line[1]).toFixed(2)+" m "+item.line[2].toFixed(2)+" "+(595-item.line[3]).toFixed(2)+" l S\n";return}
        content+="BT /F1 "+(item.size||10)+" Tf "+(item.x||20).toFixed(2)+" "+(595-(item.y||20)).toFixed(2)+" Td ("+escPdf(item.text)+") Tj ET\n";
      });
      var streamId=addObject("<< /Length "+content.length+" >>\nstream\n"+content+"endstream");
      pages.push(addObject("<< /Type /Page /Parent 0 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 "+fontId+" 0 R >> >> /Contents "+streamId+" 0 R >>"));
    });
    var kids=pages.map(function(id){return id+" 0 R"}).join(" ");
    var pagesId=addObject("<< /Type /Pages /Kids ["+kids+"] /Count "+pages.length+" >>");
    objects=objects.map(function(body){return body.replace("/Parent 0 0 R","/Parent "+pagesId+" 0 R")});
    var catalogId=addObject("<< /Type /Catalog /Pages "+pagesId+" 0 R >>");
    var pdf="%PDF-1.4\n";var xref=[0];
    objects.forEach(function(body,index){xref.push(pdf.length);pdf+=(index+1)+" 0 obj\n"+body+"\nendobj\n"});
    var xrefStart=pdf.length;pdf+="xref\n0 "+(objects.length+1)+"\n0000000000 65535 f \n";
    xref.slice(1).forEach(function(offset){pdf+=String(offset).padStart(10,"0")+" 00000 n \n"});
    pdf+="trailer\n<< /Size "+(objects.length+1)+" /Root "+catalogId+" 0 R >>\nstartxref\n"+xrefStart+"\n%%EOF";
    var blob=new Blob([pdf],{type:"application/pdf"});var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename||"document.pdf";a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},1000);
  };
  global.jspdf={jsPDF:JsPDF};
})(window);
